def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import subprocess
    import os
    from concurrent.futures import ThreadPoolExecutor
    from itertools import chunks

    if not cmd:
        raise ValueError("Command cannot be empty.")
    if target_concurrency < 1:
        raise ValueError("Target concurrency must be at least 1.")

    def _chunked_varargs(varargs, _max_length):
        current_chunk = []
        current_length = 0
        for arg in varargs:
            arg_length = len(arg) + 1  # +1 for space or null char
            if current_length + arg_length > _max_length:
                yield current_chunk
                current_chunk = []
                current_length = 0
            current_chunk.append(arg)
            current_length += arg_length
        if current_chunk:
            yield current_chunk

    def _run_command(args_chunk):
        full_cmd = cmd + tuple(args_chunk)
        if color and os.name != 'nt':
            return subprocess.run(['script', '-q', '/dev/null'] + list(full_cmd), capture_output=True, **kwargs)
        else:
            return subprocess.run(full_cmd, capture_output=True, **kwargs)

    combined_output = b''
    return_code = 0

    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        futures = {executor.submit(_run_command, chunk): chunk for chunk in _chunked_varargs(varargs, _max_length)}
        for future in futures:
            result = future.result()
            combined_output += result.stdout
            if result.returncode != 0:
                return_code = result.returncode

    return return_code, combined_output

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if not cmd:
        return cmd

    try:
        first_part = cmd[0]
        if first_part.startswith('#!'):
            # Assuming the shebang is something like '#!/usr/bin/python' which is not executable on windows
            # We need to replace it with the actual python executable path
            import sys
            python_executable = sys.executable
            return (python_executable,) + cmd[1:]
        elif ' ' in first_part and '"' not in first_part:
            # Handle cases where the first part of the command has spaces but is not quoted
            return ('"' + first_part + '"',) + cmd[1:]
        else:
            return cmd
    except Exception as e:
        # In case of any unforeseen issues, return the original command
        print(f"An error occurred: {e}")
        return cmd

