    return decorator

def extostr(cls, e, max_level=30, max_path_level=5):
    if not isinstance(e, Exception):
        raise ValueError("The provided object is not an instance of Exception.")
    if not isinstance(max_level, int) or max_level < 1:
        raise ValueError("max_level must be a positive integer.")
    if not isinstance(max_path_level, int) or max_path_level < 1:
        raise ValueError("max_path_level must be a positive integer.")

    try:
        exc_type = type(e).__name__
        exc_msg = str(e)
        stack = traceback.extract_tb(e.__traceback__)
        stack_str = []

        for level, frame in enumerate(stack[:max_level]):
            if level >= max_path_level:
                path_parts = frame.filename.split(os.sep)
                path_parts = path_parts[:1] + ['...'] + path_parts[-max_path_level+1:]
                filename = os.sep.join(path_parts)
            else:
                filename = frame.filename
            stack_str.append(f"  File \"{filename}\", line {frame.lineno}, in {frame.name}")

        return f"{exc_type}: {exc_msg}\n" + "\n".join(stack_str)
    except Exception as err:
        return f"Failed to format exception: {err}"

