def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        # Create a set to track all classes we encounter
        all_classes = set()
        # Create a dictionary to track inheritance relationships
        parents = {cls: set() for cls in classes}

        # Populate the parents dictionary with inheritance information
        for cls in classes:
            for base in cls.__bases__:
                if base in classes:
                    parents[cls].add(base)

        # Function to determine if a class is redundant
        def is_redundant(cls):
            for other in classes:
                if cls != other and issubclass(cls, other):
                    return True
            return False

        # Remove redundant classes
        minimal_classes = [cls for cls in classes if not is_redundant(cls)]

        # Sort the minimal classes based on their original order
        minimal_classes.sort(key=lambda cls: classes.index(cls))

        return minimal_classes
    except TypeError as e:
        raise ValueError("All elements in the input list must be classes.") from e
    except Exception as e:
        raise RuntimeError("An unexpected error occurred.") from e

