def difference(d1, d2, level=-1):
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both d1 and d2 must be dictionaries.")

    if level == 0:
        return {}

    result = {}
    for key, value in d1.items():
        if key not in d2:
            result[key] = value
        elif value != d2[key]:
            if isinstance(value, dict) and isinstance(d2[key], dict) and level != 1:
                diff = difference(value, d2[key], level - 1)
                if diff:
                    result[key] = diff
            else:
                result[key] = value

    return result

