            if not isinstance(key, (str, bool)):
                errors.append({key_str: 'expected string or bytes-like object (key)'})
            elif isinstance(key, str) and not key_regex.match(key):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9._-]+$'"})

            if not isinstance(value, (str, bool)):
                errors.append({value_str: 'expected string or bytes-like object (value)'})
            elif isinstance(value, str) and not value_regex.match(value):
                errors.append({value_str: f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9._-]+$'"},
            elif isinstance(value, list):
                for item in value:
                    item_str = str(item)
                    if not isinstance(item, (str, bool)):
                        errors.append({item_str: 'expected string or bytes-like object (list item)'})
                    elif isinstance(item, str) and not value_regex.match(item):
                        errors.append({item_str: f"Label value '{item_str}' does not match the regex '^[a-zA-Z0-9._-]+$'"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
        else:
            observer_schema[key] = None

    identifying_fields = {'apiVersion', 'kind', 'metadata', 'name', 'namespace'}
    if first_level:
        for field in identifying_fields:
            if field in manifest_dict:
                observer_schema[field] = manifest_dict[field]

    return observer_schema

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    if not isinstance(last_applied_manifest, list) or not isinstance(observer_schema, list) or not isinstance(response, list):
        raise ValueError("All arguments must be of type list")

    for schema_item, resp_item in zip(observer_schema, response):
        if isinstance(schema_item, dict) and isinstance(resp_item, dict):
            # Ensure last_applied_manifest has a corresponding dictionary
            if len(last_applied_manifest) < len(observer_schema):
                last_applied_manifest.append({})
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[len(last_applied_manifest) - 1], schema_item, resp_item
            )
        elif isinstance(schema_item, list) and isinstance(resp_item, list):
            # Ensure last_applied_manifest has a corresponding list
            if len(last_applied_manifest) < len(observer_schema):
                last_applied_manifest.append([])
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[len(last_applied_manifest) - 1], schema_item, resp_item
            )
        else:
            # Initialize the value in last_applied_manifest if not present
            if len(last_applied_manifest) < len(observer_schema):
                last_applied_manifest.append(None)
            if last_applied_manifest[len(last_applied_manifest) - 1] is None:
                last_applied_manifest[len(last_applied_manifest) - 1] = resp_item

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest') or not isinstance(app.spec.manifest, dict):
            raise ValueError("Invalid application specification or manifest")

        default_schema = {}
        for resource_type, resource_manifest in app.spec.manifest.items():
            if resource_type not in app.spec.observer_schema:
                default_schema[resource_type] = {
                    "type": "object",
                    "properties": {
                        "status": {"type": "object"}
                    }
                }
        return default_schema
    except Exception as e:
        raise RuntimeError(f"Failed to generate default observer schema: {e}")

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if not isinstance(sql, (str, bytes)):
        raise ValueError("sql must be of type str or bytes")

    out_style_params = []
    try:
        for params in many_params:
            if isinstance(params, Mapping):
                # Assume named parameters
                out_style_params.append({f":{key}": value for key, value in params.items()})
                sql = re.sub(r":(\w+)", lambda match: f":{match.group(1)}", sql)
            elif isinstance(params, Sequence):
                # Assume ordinal parameters
                out_style_params.append([value for value in params])
                sql = re.sub(r"\?", ":%s", sql % tuple(range(len(params))))
            else:
                raise ValueError("each params in many_params must be a Mapping or Sequence")
    except TypeError:
        raise ValueError("many_params must be an Iterable of Mappings or Sequences")

    return sql, out_style_params

