        raise ValueError("The prior version timestamp must be earlier than the current version timestamp.")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")
    if not isinstance(version, str):
        raise ValueError("Version must be a string.")

    path_map = {}

    try:
        for logical_path, details in inventory.items():
            if not isinstance(details, dict) or 'versions' not in details:
                continue
            if version in details['versions']:
                files = details['versions'][version].get('files', [])
                if logical_path not in path_map:
                    path_map[logical_path] = set()
                path_map[logical_path].update(files)

                # Include duplicates from later versions
                for v in sorted(details['versions'].keys(), key=lambda x: x if x == version else x + 'z'):
                    if v > version:
                        later_files = details['versions'][v].get('files', [])
                        path_map[logical_path].update(later_files)

    except Exception as e:
        raise RuntimeError(f"An error occurred while processing the inventory: {e}")

    return path_map

