def _explore_folder(folder):
    import os
    import xml.etree.ElementTree as ET

    if not isinstance(folder, str):
        raise ValueError("Folder must be a string")
    if not os.path.isdir(folder):
        raise ValueError("Folder does not exist or is not a directory")

    package_data = {}

    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                base_name = os.path.splitext(file)[0]

                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()
                    # Assuming we want to capture all XML data, adjust as needed
                    data = ET.tostring(root_element, encoding='unicode')
                except ET.ParseError:
                    print(f"Warning: Could not parse XML file {file_path}")
                    continue

                if base_name not in package_data:
                    package_data[base_name] = []
                package_data[base_name].append(data)

    return package_data

