def pretty(self, indent=0, debug=False):
    try:
        indent_str = '  ' * indent
        result = f"{indent_str}<{self.__class__.__name__}>\n"
        for key, value in self.__dict__.items():
            if isinstance(value, (list, tuple, set, dict)) and len(value) > 0:
                result += f"{indent_str}  {key}:\n"
                for item in value:
                    if hasattr(item, 'pretty'):
                        result += item.pretty(indent + 2, debug=debug) + "\n"
                    else:
                        result += f"{indent_str}    {item}\n"
            elif hasattr(value, 'pretty'):
                result += f"{indent_str}  {key}:\n"
                result += value.pretty(indent + 2, debug=debug) + "\n"
            else:
                result += f"{indent_str}  {key}: {value}\n"
        result += f"{indent_str}</{self.__class__.__name__}>\n"
        return result
    except Exception as e:
        if debug:
            return f"{indent_str}<ERROR: {str(e)}>\n"
        return ""

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, list):
        raise ValueError("args must be a list of expressions")

    def apply_absorption(expr):
        if len(expr) != 3:
            return expr
        op, a, b = expr
        if isinstance(b, tuple) and len(b) == 3:
            sub_op, sub_a, sub_b = b
            if op == '&' and sub_op == '|' and a == sub_a:
                return a
            if op == '|' and sub_op == '&' and a == sub_a:
                return a
            if op == '&' and sub_op == '|' and a == ('~', sub_a):
                return (op, a, sub_b)
            if op == '|' and sub_op == '&' and a == ('~', sub_a):
                return (op, a, sub_b)
        return expr

    try:
        return [apply_absorption(expr) for expr in args]
    except Exception as e:
        raise ValueError(f"Error processing expression: {e}")

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def decorator(func):
        try:
            if not callable(func):
                raise ValueError("The provided handler must be callable.")
            if hook not in self.registry:
                self.registry[hook] = []
            self.registry[hook].append(func)
            return func
        except Exception as e:
            print(f"An error occurred while registering the handler: {e}")
            raise
    return decorator

