def _fromutc(self, dt):
    if not isinstance(dt, datetime.datetime) or dt.tzinfo is None:
        raise ValueError("dt must be a timezone-aware datetime object")

    # Convert the given UTC datetime to the timezone of self
    local_dt = dt.astimezone(self)

    # Check if the local datetime is in the fold (ambiguous time)
    fold = 0
    try:
        self.localize(dt.replace(tzinfo=None), is_dst=False)
        fold = 1
    except pytz.NonExistentTimeError:
        fold = 0
    except pytz.AmbiguousTimeError:
        fold = 1

    return local_dt.replace(fold=fold)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        result = namefunc()
        if isinstance(result, tuple) and all(isinstance(item, unicode) for item in result):
            return tuple(item.encode('utf-8') for item in result)
        return result
    except Exception as e:
        return str(e)

