def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, (list, str)):
        raise ValueError("Commands must be a list or a string.")
    if not isinstance(args, list):
        raise ValueError("Arguments must be a list.")
    if cwd and not os.path.isdir(cwd):
        raise ValueError("Current working directory must be a valid directory.")

    full_command = [commands] if isinstance(commands, str) else commands
    full_command.extend(args)

    try:
        subprocess_kwargs = {
            'cmd': full_command,
            'cwd': cwd,
            'env': os.environ.update(env) if env else None,
            'stdout': subprocess.PIPE if verbose else subprocess.DEVNULL,
            'stderr': subprocess.DEVNULL if hide_stderr else subprocess.PIPE
        }

        if verbose:
            print(f"Running command: {' '.join(full_command)}")

        result = subprocess.run(**subprocess_kwargs, capture_output=True, text=True)
        if result.returncode != 0:
            print(f"Command failed with return code {result.returncode}")
            if result.stderr:
                print(f"Error output: {result.stderr}")

        return result.returncode, result.stdout, result.stderr

    except Exception as e:
        print(f"An error occurred: {e}")
        return 1, "", str(e)

