    try:
        for obj in self.get_objects():
            num_objects += 1
            is_valid = True

            if validate_objects:
                if not obj.is_valid():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Object {obj} is not valid.")

            if check_digests:
                if not obj.check_digest():
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: Digest check failed for object {obj}.")

            if is_valid:
                good_objects += 1

