def validate_version_inventories(self, version_dirs):
    if not isinstance(version_dirs, list) or not all(isinstance(d, str) for d in version_dirs):
        raise ValueError("version_dirs must be a list of strings")

    root_inventory = self.get_root_inventory()  # Assuming a method to retrieve the root inventory
    differing_digests = {}

    for version in version_dirs:
        try:
            version_inventory = self.get_version_inventory(version)  # Assuming a method to retrieve inventory for a version
        except FileNotFoundError:
            print(f"Warning: Inventory for version {version} not found. Skipping validation for this version.")
            continue
        except Exception as e:
            raise RuntimeError(f"An error occurred while retrieving inventory for version {version}: {str(e)}")

        if set(version_inventory.keys()) != set(root_inventory.keys()):
            print(f"Version {version} inventory does not have the same entries as the root inventory.")

        for key, digest in version_inventory.items():
            if root_inventory.get(key) != digest:
                if key not in differing_digests:
                    differing_digests[key] = set()
                differing_digests[key].add(digest)

    for key, digests in differing_digests.items():
        if len(digests) > 1:
            print(f"Content digest for key '{key}' differs across versions: {digests}")

    return differing_digests

def find_path_type(path):
    import os

    if not path or not isinstance(path, str):
        return "invalid path input"

    if not os.path.exists(path):
        return "path does not exist"

    try:
        if os.path.isfile(path):
            return "file"

        namaste_file = "0=ocfl_1.0"
        namaste_path = os.path.join(path, namaste_file)

        if os.path.exists(namaste_path) and os.path.isfile(namaste_path):
            if os.path.basename(path) == 'inventory.json':
                return "object"
            else:
                return "root"

        return "unknown OCFL path type"

    except Exception as e:
        return f"error checking path: {str(e)}"

