def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_values(key, value, result_dict):
        key_value = key.value
        if key_value in result_dict:
            existing_value = result_dict[key_value]
            if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                merged_value = defaultdict(list)
                for k, v in existing_value.value + value.value:
                    merged_value[k.value].append(v)
                for k, v_list in merged_value.items():
                    if len(v_list) > 1:
                        merge_values(k, v_list[-1], merged_value)
                    else:
                        merged_value[k.value] = v_list[0]
                result_dict[key_value] = MappingNode(tag='tag:yaml.org,2002:map', value=list(merged_value.items()))
            else:
                result_dict[key_value] = value
        else:
            result_dict[key_value] = value

    result_dict = {}
    for key, value in nodes:
        merge_values(key, value, result_dict)

    return [(ScalarNode(tag=key.tag, value=key_value), value) for key_value, value in result_dict.items()]

