def parse_arguments(*unparsed_arguments):
    import argparse

    parser = argparse.ArgumentParser(description='Process some command-line arguments.')
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example subparser configuration
    parser_a = subparsers.add_parser('subparser_a', help='Subparser A help')
    parser_a.add_argument('foo', type=int, help='foo help')

    parser_b = subparsers.add_parser('subparser_b', help='Subparser B help')
    parser_b.add_argument('bar', type=str, help='bar help')

    # Global arguments
    parser.add_argument('--global_arg', type=str, help='Global argument help')

    try:
        args = parser.parse_args(unparsed_arguments)
    except SystemExit:
        # Catch the SystemExit exception thrown by ArgumentParser for incorrect arguments
        return {}

    result = {'global': argparse.Namespace()}
    if args.global_arg:
        result['global'].global_arg = args.global_arg

    if args.subparser_name:
        result[args.subparser_name] = args

    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
