    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            # Use parse_known_args to handle common arguments and identify remaining arguments
            parsed_namespace, remaining = parser.parse_known_args(remaining_arguments)
            parsed_results[subparser_name] = parsed_namespace
            remaining_arguments = remaining
        except SystemExit:
            # This exception is raised by ArgumentParser.error() which is called if argument parsing fails
            continue
        except Exception as e:
            # Handle any other unexpected exceptions
            continue

    return parsed_results, remaining_arguments

def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_values(key, value, merged_dict):
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            if key not in merged_dict:
                merged_dict[key] = defaultdict(list)
            for sub_key, sub_value in value.value:
                merge_values(sub_key, sub_value, merged_dict[key])
        else:
            merged_dict[key] = value

    merged_dict = defaultdict(list)
    for key, value in nodes:
        merge_values(key, value, merged_dict)

    result = []
    for key, value in merged_dict.items():
        if isinstance(value, defaultdict):
            # Convert defaultdict back to a MappingNode
            sub_nodes = [(sub_key, sub_value) for sub_key, sub_value in value.items()]
            result.append((key, ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=sub_nodes)))
        else:
            result.append((key, value))

    return result

