def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import argparse
        import borgmatic.commands
    except ImportError as e:
        return f"# Error: {e}. Please ensure borgmatic is installed."

    def get_parser_actions(parser):
        actions = []
        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for subparser_action in action._choices_actions:
                    actions.append((subparser_action.dest, subparser_action.choices))
            else:
                actions.append(action)
        return actions

    def generate_completions(parser, command=''):
        completions = []
        for action in get_parser_actions(parser):
            if isinstance(action, tuple):
                subcommand, subparsers = action
                for subcommand_name, subparser in subparsers.items():
                    if command:
                        full_command = f"{command} {subcommand_name}"
                    else:
                        full_command = subcommand_name
                    completions.append(f"    {full_command})\n")
                    completions.extend(generate_completions(subparser, full_command))
                    completions.append(f"        ;;\n")
            else:
                if action.option_strings:
                    for option in action.option_strings:
                        completions.append(f"        {option} ")
                        if action.metavar:
                            completions.append(f"{action.metavar} ")
                        completions.append(f"\\n")
        return completions

    try:
        borgmatic_parser = borgmatic.commands.parsers.generate_subparsers()
        completion_script = [
            "# START BASH COMPLETION FOR BORGMAITIC",
            "_borgmatic()",
            "{",
            "    local cur prev opts",
            "    COMPREPLY=()",
            "    cur=\"${COMP_WORDS[COMP_CWORD]}\"",
            "    prev=\"${COMP_WORDS[COMP_CWORD-1]}\"",
            "    opts=\"\"",
            ""
        ]
        completion_script.extend(generate_completions(borgmatic_parser))
        completion_script.extend([
            "    case ${cur} in",
            "        --*)",
            "            COMPREPLY=( $(compgen -W \"${opts}\" -- ${cur}) )",
            "            return 0",
            "            ;;",
            "    esac",
            "}",
            "complete -F _borgmatic borgmatic",
            "# END BASH COMPLETION FOR BORGMAITIC"
        ])
        return "\n".join(completion_script)
    except Exception as e:
        return f"# Error generating bash completion: {e}"

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_results = {}
    remaining_arguments = unparsed_arguments.copy()

    for subparser_name, parser in subparsers.items():
        try:
            # Attempt to parse all arguments with the current subparser
            parsed_namespace, extras = parser.parse_known_args(remaining_arguments)
            parsed_results[subparser_name] = parsed_namespace
            # Update remaining arguments to those not claimed by this subparser
            remaining_arguments = extras
        except Exception as e:
            # If parsing fails, log the exception and continue with next subparser
            print(f"Failed to parse arguments for {subparser_name}: {str(e)}")
            parsed_results[subparser_name] = None

    return parsed_results, remaining_arguments

