def was_processed(processed, path_name, verbose):
    import os

    if not isinstance(processed, set):
        raise ValueError("The 'processed' parameter must be a set.")
    if not isinstance(path_name, str):
        raise ValueError("The 'path_name' parameter must be a string.")
    if not isinstance(verbose, bool):
        raise ValueError("The 'verbose' parameter must be a boolean.")

    try:
        abs_path_name = os.path.abspath(path_name)
    except Exception as e:
        raise ValueError(f"Failed to get absolute path for '{path_name}': {e}")

    if abs_path_name in processed:
        if verbose:
            print(f"Path '{abs_path_name}' has already been processed.")
        return True
    else:
        processed.add(abs_path_name)
        return False

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet list cannot be empty.")
    if number < 0:
        raise ValueError("Number must be non-negative.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters to form a valid base.")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number > 0:
        digits.append(alphabet[number % base])
        number //= base

    result = ''.join(reversed(digits))

    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

