def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:
        # POSIX compatible splitting
        return re.findall(r"""(?:(?<=\s|^)'(.*?)(?=\s|$)'|(?:(?<=\s|^)"(.*?)(?=\s|$)")|(?:[^\s'"]+)""", s)
    elif platform == 0:
        # Windows/CMD compatible splitting
        return re.findall(r"""(?:\"(.*?)\")|(?:(\S+))""", s)
    else:
        raise ValueError("Unsupported platform value. Use 'this', 1, or 0.")

    # Extract non-empty matches
    return [match[0] or match[1] for match in result if any(match)]

def addignored(ignored):
    try:
        # Run the git command to list ignored files
        result = subprocess.run(['git', 'check-ignore', '-v', ignored], capture_output=True, text=True, check=True)

        # Split the output into lines and extract file names
        ignored_files = set()
        for line in result.stdout.splitlines():
            parts = line.split()
            if len(parts) > 2:
                ignored_files.add(parts[2])

        # Sort the list of ignored files
        sorted_ignored_files = sorted(ignored_files)

        # Join the sorted file names into a single string separated by commas
        return ','.join(sorted_ignored_files)

    except subprocess.CalledProcessError as e:
        # Handle the case where the git command fails
        print(f"Error: {e.stderr.strip()}")
        return ""
    except Exception as e:
        # Handle any other exceptions
        print(f"An unexpected error occurred: {str(e)}")
        return ""

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        value, unit = frequency.split()
        value = int(value)
    except ValueError:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    unit = unit.lower()
    if unit in ["second", "seconds"]:
        return datetime.timedelta(seconds=value)
    elif unit in ["minute", "minutes"]:
        return datetime.timedelta(minutes=value)
    elif unit in ["hour", "hours"]:
        return datetime.timedelta(hours=value)
    elif unit in ["day", "days"]:
        return datetime.timedelta(days=value)
    elif unit in ["week", "weeks"]:
        return datetime.timedelta(weeks=value)
    else:
        raise ValueError(f"Unrecognized time unit: {unit}")

def make_find_paths(find_paths):
