def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    try:
        # Find all nodes that are used as children in the (child, prop, parent) triples
        all_children = {triple[0] for triple in graph.triples((None, prop, None))}

        # Find all nodes that are used as parents in the (child, prop, parent) triples
        all_parents = {triple[2] for triple in graph.triples((None, prop, None))}

        # Roots are nodes that are parents but not children
        roots.update(all_parents - all_children)

        # Recursively find roots among the parents
        for parent in all_parents:
            find_roots(graph, prop, roots)

    except Exception as e:
        print(f"An error occurred: {e}")

    return roots

