def isoparse(self, dt_str):
    from dateutil import parser
    try:
        # Use the isoparse method from dateutil.parser to parse the datetime string
        parsed_datetime = parser.isoparse(dt_str)
        return parsed_datetime
    except (ValueError, TypeError) as e:
        # Handle invalid input gracefully
        raise ValueError(f"Invalid ISO-8601 datetime string: {dt_str}") from e

def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    try:
        if not isinstance(timestr, str):
            raise TypeError("Input must be a string")

        if default is not None and not isinstance(default, datetime.datetime):
            raise ValueError("Default must be a datetime object or None")

        import dateutil.parser
        result = dateutil.parser.parse(timestr, default=default, ignoretz=ignoretz, tzinfos=tzinfos, **kwargs)
        return result

    except dateutil.parser.ParserError:
        raise ValueError("Invalid or unknown string format")
    except OverflowError:
        raise OverflowError("Parsed date exceeds the largest valid C integer on your system")
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred: {e}")

def default_tzinfo(dt, tzinfo):
    if not isinstance(dt, datetime.datetime):
        raise TypeError("The first argument must be an instance of datetime.datetime")
    if not isinstance(tzinfo, datetime.tzinfo):
        raise TypeError("The second argument must be an instance of datetime.tzinfo")

    if dt.tzinfo is None:
        return dt.replace(tzinfo=tzinfo)
    return dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
