        if 'User-Agent' in headers and 'MatrixHttpClient' in headers['User-Agent']:
            return True
        if 'Accept' in headers and 'application/json' in headers['Accept'] and 'matrix.org' in headers.get('Origin', ''):
            return True
        # Additional checks can be added here based on other request properties
    except AttributeError:
        # Handle the case where request does not have the expected attributes
        pass
    except Exception as e:
