def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise ValueError("Input must be a string.")

    # A valid tag should not be empty and should not contain spaces or special characters
    # except for underscores and hyphens which are often used in tags.
    if not tag:
        return False

    if tag.strip() != tag:
        return False  # Tags should not have leading or trailing whitespace

    valid_characters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"
    for char in tag:
        if char not in valid_characters:
            return False

    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        try:
            if child.tag not in result:
                result[child.tag] = child.text
            else:
                # If there are multiple children with the same tag, store them in a list
                if not isinstance(result[child.tag], list):
                    result[child.tag] = [result[child.tag]]
                result[child.tag].append(child.text)
        except AttributeError:
            # Handle the case where the node does not have a tag or text attribute
            continue
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    try:
        if not isinstance(url, str) or not url:
            raise ValueError("Invalid URL provided.")

        if document_path and not isinstance(document_path, str):
            raise ValueError("Invalid document path provided.")

        base_url = url.rstrip('/')
        nodeinfo_path = document_path or "/.well-known/nodeinfo"
        full_url = f"{base_url}{nodeinfo_path}"

        return {
            "links": [
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/2.1",
                    "href": f"{full_url}/2.1"
                },
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                    "href": f"{full_url}/2.0"
                }
            ]
        }
    except Exception as e:
        return {"error": str(e)}

def parse_diaspora_webfinger(document: str) -> Dict:
    import json
    from xml.etree import ElementTree as ET

    try:
        # Try to parse as JSON first
        data = json.loads(document)
        if "links" in data:
            return data
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XML (XRD)
        try:
            root = ET.fromstring(document)
            if root.tag == '{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD':
                result = {'links': []}
                for link in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                    link_data = {attr: link.attrib[attr] for attr in link.attrib}
                    result['links'].append(link_data)
                return result
        except ET.ParseError:
            pass
    raise ValueError("Document is not in a valid JSON or XRD format")

