def dict_insert(dic, val, key, *keys):
    try:
        current = dic
        for k in (key,) + keys[:-1]:
            if k not in current or not isinstance(current[k], dict):
                current[k] = {}
            current = current[k]
        current[keys[-1]] = val
    except TypeError:
        raise ValueError("All keys must be hashable types")
    except Exception as e:
        raise RuntimeError(f"An error occurred while inserting the value: {e}")

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    if not isinstance(settings_dirs, list) or not all(isinstance(d, str) for d in settings_dirs):
        raise ValueError("settings_dirs must be a list of strings")
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string")

    file_names = []
    try:
        for directory in settings_dirs:
            import os
            if os.path.isdir(directory):
                files = os.listdir(directory)
                for file in files:
                    if file.endswith(spec_option):
                        file_names.append(os.path.join(directory, file))
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

    return file_names

