    if not yaml_file or not isinstance(yaml_file, str):
        raise ValueError("yaml_file must be a valid string path")

    if not path.isfile(yaml_file):
        raise FileNotFoundError(f"The file {yaml_file} does not exist")

    with open(yaml_file, 'r') as file:
        try:
            data = yaml.safe_load(file)
        except yaml.YAMLError as e:
            raise ValueError(f"Error parsing YAML file: {e}")

    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a valid dictionary")

    required_fields = {'field1', 'field2', 'field3'}  # Example required fields
    missing_fields = required_fields - data.keys()

    if missing_fields:
        raise IRValidatorException(f"Mandatory fields missing in the YAML file: {missing_fields}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dictionary")

    try:
        include_dict = parser_dict.get('include', {})
        if not isinstance(include_dict, dict):
            raise ValueError("include directive must be a dictionary")

        resolved_dict = {}
        for key, value in parser_dict.items():
            if key == 'include':
                for include_key, include_value in include_dict.items():
                    if include_key in parser_dict:
                        raise KeyError(f"Conflict with include key: {include_key}")
                    resolved_dict[include_key] = include_value
            else:
                resolved_dict[key] = value

        return resolved_dict

    except Exception as e:
        raise RuntimeError(f"Error resolving include groups: {e}")

def get_spec_defaults(self):
