def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_args = []
    if not isinstance(command_name, str) or not isinstance(options_spec, list) or not isinstance(args, dict):
        raise ValueError("Invalid input types")

    for option in options_spec:
        try:
            required_when = option.get('required_when', {})
            for condition, condition_value in required_when.items():
                if condition in args and args[condition] == condition_value:
                    required_args.append(option['name'])
        except Exception as e:
            raise ValueError(f"Error processing option spec: {e}")

    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    for key, value in args.items():
        if isinstance(value, str) and hasattr(key, 'max_length'):
            max_length = getattr(key, 'max_length', None)
            if max_length is not None and len(value) > max_length:
                raise ValueError(f"Value for '{key}' is longer than the maximum allowed length of {max_length}.")
        elif not isinstance(value, str) and not isinstance(value, collections.abc.Sized):
            raise TypeError(f"Value for '{key}' must be a string or a sized object to check length.")
        elif isinstance(value, collections.abc.Sized) and hasattr(key, 'max_length'):
            max_length = getattr(key, 'max_length', None)
            if max_length is not None and len(value) > max_length:
                raise ValueError(f"Value for '{key}' is longer than the maximum allowed length of {max_length}.")

def validate_choices_args(self, args):
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    for arg_name, arg_value in args.items():
        choices = getattr(self, f"{arg_name}_choices", None)
        if choices is not None and arg_value not in choices:
            raise ValueError(f"Invalid choice for '{arg_name}': {arg_value}. Available choices are: {choices}.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise ValueError("Arguments must be provided as a dictionary.")

    for arg_name, arg_value in args.items():
        if not isinstance(arg_value, dict) or 'value' not in arg_value or 'min' not in arg_value or 'max' not in arg_value:
            raise ValueError(f"Each argument must be a dictionary with 'value', 'min', and 'max' keys. Invalid argument: {arg_name}")

        value = arg_value['value']
        min_value = arg_value['min']
        max_value = arg_value['max']

        if not isinstance(value, (int, float)) or not isinstance(min_value, (int, float)) or not isinstance(max_value, (int, float)):
            raise ValueError(f"Values for 'value', 'min', and 'max' must be numbers. Invalid argument: {arg_name}")

        if value < min_value or value > max_value:
            raise ValueError(f"Value for {arg_name} is out of range. Expected between {min_value} and {max_value}, got {value}.")

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a non-empty string")
        if not isinstance(spec_option, dict) or not spec_option:
            raise ValueError("spec_option must be a non-empty dictionary")

        # Assuming a complex type instance is created based on the provided specifications
        complex_type_instance = {
            "subcommand": subcommand,
            "type_name": type_name,
            "option_name": option_name,
            "spec_option": spec_option
        }
        return complex_type_instance

    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if not isinstance(args, dict):
        raise ValueError("Input must be a dictionary")

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        if key.startswith('control_'):
            control_args[key] = value
        elif key.startswith('custom_'):
            nested_args[key[len('custom_'):]] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if extra_vars is None:
        extra_vars = []

    if not isinstance(extra_vars, list):
        raise ValueError("extra_vars must be a list")

    for extra_var in extra_vars:
        if not isinstance(extra_var, dict):
            raise ValueError("Each element in extra_vars must be a dictionary")
        vars_dict.update(extra_var)

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    try:
        command = ['ansible-playbook', playbook_path]

        if verbose is not None:
            command.extend(['-' + 'v' * verbose])

        if extra_vars:
            command.extend(['--extra-vars', ' '.join(f'{k}={v}' for k, v in extra_vars.items())])

        if ansible_args:
            for k, v in ansible_args.items():
                flag = f'--{k.replace("_", "-")}'
                if v is not None:
                    command.extend([flag, str(v)])
                else:
                    command.append(flag)

        # Assuming ir_workspace and ir_plugin have a method to execute a command
        return ir_workspace.execute_command(command)

    except Exception as e:
        raise Exception(f"An error occurred while executing ansible-playbook: {str(e)}")

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise ValueError("values_dict must be a dictionary")

    if parser_name == 'main':
        try:
            values_dict['count'] = int(values_dict.get('count', 0))
            values_dict['enable'] = values_dict.get('enable', 'false').lower() in ['true', '1', 't']
        except ValueError as e:
            raise ValueError(f"Error converting arguments for {parser_name}: {e}")
    elif parser_name == 'virsh':
        try:
            values_dict['domain_id'] = int(values_dict.get('domain_id', 0))
            values_dict['active'] = values_dict.get('active', 'false').lower() in ['true', '1', 't']
        except ValueError as e:
            raise ValueError(f"Error converting arguments for {parser_name}: {e}")
    elif parser_name == 'ospd':
        try:
            values_dict['port'] = int(values_dict.get('port', 8080))
            values_dict['use_ssl'] = values_dict.get('use_ssl', 'false').lower() in ['true', '1', 't']
        except ValueError as e:
            raise ValueError(f"Error converting arguments for {parser_name}: {e}")
    # Add more parser_name conditions as needed

    # Default conversion for unknown parser_name or additional arguments
    for key, value in values_dict.items():
        if isinstance(value, str):
            if value.isdigit():
                values_dict[key] = int(value)
            elif value.lower() in ['true', 'false', '1', '0', 't', 'f']:
                values_dict[key] = value.lower() in ['true', '1', 't']

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    from collections import OrderedDict

    def flatten(d, parent_key='', sep='.'):
        """ Helper function to flatten a dictionary """
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    try:
        spec_file_path = os.path.join(plugin_dir, 'plugin_spec.json')
        if not os.path.isfile(spec_file_path):
            raise FileNotFoundError(f"Plugin spec file not found at {spec_file_path}")

        with open(spec_file_path, 'r') as file:
            plugin_spec = json.load(file, object_pairs_hook=OrderedDict)

        return flatten(plugin_spec)

    except FileNotFoundError as e:
        raise e
    except json.JSONDecodeError as e:
        raise ValueError(f"Error decoding JSON from plugin spec file: {e}")
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred: {e}")

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os

    config_path_env = 'CONFIG_PATH'
    if config_path_env not in os.environ:
        try:
            # Example default path, can be changed as needed
            default_config_path = '/path/to/default/config'
            os.environ[config_path_env] = default_config_path
            print(f"Set default config path to: {default_config_path}")
        except Exception as e:
            print(f"Failed to set environment variable {config_path_env}: {e}")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise ValueError("Both path and root must be strings.")
    if not root:
        raise ValueError("Root must not be an empty string.")
    if not path.startswith(root):
        raise ValueError("Path does not start with the specified root.")
    stripped_path = path[len(root):]
    # Remove any leading separator from the stripped path if it exists
    if stripped_path and stripped_path[0] in ('/', '\\'):
        stripped_path = stripped_path[1:]
    return stripped_path
